function add(x, y) { return x + y; }

var add5 = add.bind(null, 5);            // 5 fixed as leading argument
add5(3);                                 // 8

// receiver and prefix bound together:
var log = console.log.bind(console, '[app]');

import * as R from 'ramda';

const add = R.curry((x, y) => x + y);
add(1)(2);            // 3
add(1, 2);            // 3 - arity-driven, either style works

const incAll = R.map(R.add(1));   // data-last, point-free
